#include <iostream>
using namespace std;

int main() {
    int numar;
    cout << "Introdu un numar: ";
    cin >> numar;

    if (numar % 2 == 0) {
        cout << "Numarul este PAR" << endl;
    } else {
        cout << "Numarul este IMPAR" << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int varsta;
    cout << "Introdu varsta: ";
    cin >> varsta;

    if (varsta < 13) {
        cout << "Copil" << endl;
    } else if (varsta < 18) {
        cout << "Adolescent" << endl;
    } else if (varsta < 65) {
        cout << "Adult" << endl;
    } else {
        cout << "Senior" << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int nota;
    cout << "Introdu nota: ";
    cin >> nota;

    if (nota == 10) {
        cout << "Excelent!" << endl;
    } else if (nota >= 7) {
        cout << "Bine" << endl;
    } else if (nota >= 5) {
        cout << "Suficient" << endl;
    } else {
        cout << "Insuficient" << endl;
    }

    return 0;
}

